command:
perl -MCompress::Raw::Zlib=crc32 -e '
my $target = 0xb0725dc4;
my $prefix = "PASSWORD=8XDP5Q2RT9Z";
my $suffix = "VB3BV4WW54\n";
my @chars = ("A".."Z", 0..9);
my $count = 0;
open(my $out, ">", "/app/recovered_passwords.txt") or die $!;
for my $a (@chars) {
  for my $b (@chars) {
    my $pw = "8XDP5Q2RT9Z" . $a . $b . "VB3BV4WW54";
    my $content = $prefix . $a . $b . $suffix;
    my $crc = crc32($content);
    if ($crc == $target) {
      print "MATCH: $pw (length ", length($pw), ")\n";
      print $out "$pw\n";
      $count++;
    }
  }
}
close($out);
print "total matches written: $count\n";
' && echo '--- /app/recovered_passwords.txt ---' && cat /app/recovered_passwords.txt && echo '--- validation ---' && wc -c /app/recovered_passwords.txt
